  "a": { ru: "a", uk: "a" },
  "Enter the URLs of layers hosted on the web. The custom navigator will open these layers by default.": { ru: "\u0423\u043A\u0430\u0436\u0438\u0442\u0435 URL \u0441\u043B\u043E\u0451\u0432, \u0440\u0430\u0437\u043C\u0435\u0449\u0451\u043D\u043D\u044B\u0445 \u0432 \u0438\u043D\u0442\u0435\u0440\u043D\u0435\u0442\u0435. \u041D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u044B\u0439 \u043D\u0430\u0432\u0438\u0433\u0430\u0442\u043E\u0440 \u0431\u0443\u0434\u0435\u0442 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0442\u044C \u0438\u0445 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E.", uk: "\u0412\u043A\u0430\u0436\u0456\u0442\u044C URL \u0448\u0430\u0440\u0456\u0432, \u0440\u043E\u0437\u043C\u0456\u0449\u0435\u043D\u0438\u0445 \u0432 \u0456\u043D\u0442\u0435\u0440\u043D\u0435\u0442\u0456. \u041D\u0430\u043B\u0430\u0448\u0442\u043E\u0432\u0430\u043D\u0438\u0439 \u043D\u0430\u0432\u0456\u0433\u0430\u0442\u043E\u0440 \u0442\u0438\u043F\u043E\u0432\u043E \u0432\u0456\u0434\u043A\u0440\u0438\u0432\u0430\u0442\u0438\u043C\u0435 \u0446\u0456 \u0448\u0430\u0440\u0438." },
  "Navigator Features": { ru: "\u0424\u0443\u043D\u043A\u0446\u0438\u0438 \u041D\u0430\u0432\u0438\u0433\u0430\u0442\u043E\u0440\u0430", uk: "\u0424\u0443\u043D\u043A\u0446\u0456\u0457 \u041D\u0430\u0432\u0456\u0433\u0430\u0442\u043E\u0440\u0430" },
  "custom navigator url": { ru: "url \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u043E\u0433\u043E \u043D\u0430\u0432\u0438\u0433\u0430\u0442\u043E\u0440\u0430", uk: "url \u043D\u0430\u043B\u0430\u0448\u0442\u043E\u0432\u0430\u043D\u043E\u0433\u043E \u043D\u0430\u0432\u0456\u0433\u0430\u0442\u043E\u0440\u0430" },
  "copy": { ru: "\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C", uk: "\u043A\u043E\u043F\u0456\u044E\u0432\u0430\u0442\u0438" },
  "copied": { ru: "\u0441\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u043D\u043E", uk: "\u0441\u043A\u043E\u043F\u0456\u0439\u043E\u0432\u0430\u043D\u043E" },
  "Selection Controls": { ru: "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0432\u044B\u0431\u043E\u0440\u043E\u043C", uk: "\u041A\u0435\u0440\u0443\u0432\u0430\u043D\u043D\u044F \u0432\u0438\u0431\u043E\u0440\u043E\u043C" },
  "Layer Controls": { ru: "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u043B\u043E\u0435\u043C", uk: "\u041A\u0435\u0440\u0443\u0432\u0430\u043D\u043D\u044F \u0448\u0430\u0440\u043E\u043C" },
  "Technique Controls": { ru: "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0442\u0435\u0445\u043D\u0438\u043A\u0430\u043C\u0438", uk: "\u041A\u0435\u0440\u0443\u0432\u0430\u043D\u043D\u044F \u0442\u0435\u0445\u043D\u0456\u043A\u0430\u043C\u0438" },
  "search & multiselect": { ru: "\u043F\u043E\u0438\u0441\u043A \u0438 \u043C\u0443\u043B\u044C\u0442\u0438\u0432\u044B\u0431\u043E\u0440", uk: "\u043F\u043E\u0448\u0443\u043A \u0456 \u043C\u0443\u043B\u044C\u0442\u0438\u0432\u0438\u0431\u0456\u0440" },
  "search": { ru: "\u043F\u043E\u0438\u0441\u043A", uk: "\u043F\u043E\u0448\u0443\u043A" },
  "Deselect": { ru: "\u0421\u043D\u044F\u0442\u044C \u0432\u044B\u0431\u043E\u0440", uk: "\u0417\u043D\u044F\u0442\u0438 \u0432\u0438\u0431\u0456\u0440" },
  "selection behavior": { ru: "\u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0432\u044B\u0431\u043E\u0440\u0430", uk: "\u043F\u043E\u0432\u0435\u0434\u0456\u043D\u043A\u0430 \u0432\u0438\u0431\u043E\u0440\u0443" },
  "select techniques across tactics": { ru: "\u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u0442\u0435\u0445\u043D\u0438\u043A\u0438 \u0432\u043E \u0432\u0441\u0435\u0445 \u0442\u0430\u043A\u0442\u0438\u043A\u0430\u0445", uk: "\u0432\u0438\u0431\u0438\u0440\u0430\u0442\u0438 \u0442\u0435\u0445\u043D\u0456\u043A\u0438 \u0432 \u0443\u0441\u0456\u0445 \u0442\u0430\u043A\u0442\u0438\u043A\u0430\u0445" },
  "select sub-techniques with parent": { ru: "\u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u043F\u043E\u0434\u0442\u0435\u0445\u043D\u0438\u043A\u0438 \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u0440\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u0441\u043A\u043E\u0439", uk: "\u0432\u0438\u0431\u0438\u0440\u0430\u0442\u0438 \u043F\u0456\u0434\u0442\u0435\u0445\u043D\u0456\u043A\u0438 \u0440\u0430\u0437\u043E\u043C \u0437 \u0431\u0430\u0442\u044C\u043A\u0456\u0432\u0441\u044C\u043A\u043E\u044E" },
  "select only visible techniques": { ru: "\u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u0438\u0434\u0438\u043C\u044B\u0435 \u0442\u0435\u0445\u043D\u0438\u043A\u0438", uk: "\u0432\u0438\u0431\u0438\u0440\u0430\u0442\u0438 \u043B\u0438\u0448\u0435 \u0432\u0438\u0434\u0438\u043C\u0456 \u0442\u0435\u0445\u043D\u0456\u043A\u0438" },
  "selection control settings": { ru: "\u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u0432\u044B\u0431\u043E\u0440\u043E\u043C", uk: "\u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u043A\u0435\u0440\u0443\u0432\u0430\u043D\u043D\u044F \u0432\u0438\u0431\u043E\u0440\u043E\u043C" },
  "Show Control Labels": { ru: "\u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u043F\u043E\u0434\u043F\u0438\u0441\u0438 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u043E\u0432 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F", uk: "\u041F\u043E\u043A\u0430\u0437\u0443\u0432\u0430\u0442\u0438 \u043F\u0456\u0434\u043F\u0438\u0441\u0438 \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0456\u0432 \u043A\u0435\u0440\u0443\u0432\u0430\u043D\u043D\u044F" },
  "Included Controls:": { ru: "\u0412\u043A\u043B\u044E\u0447\u0451\u043D\u043D\u044B\u0435 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F:", uk: "\u0423\u0432\u0456\u043C\u043A\u043D\u0435\u043D\u0456 \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0438 \u043A\u0435\u0440\u0443\u0432\u0430\u043D\u043D\u044F:" },
  "layer settings": { ru: "\u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0441\u043B\u043E\u044F", uk: "\u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0448\u0430\u0440\u0443" },
  "layer information": { ru: "\u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044F \u043E \u0441\u043B\u043E\u0435", uk: "\u0456\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0456\u044F \u043F\u0440\u043E \u0448\u0430\u0440" },
  "export": { ru: "\u044D\u043A\u0441\u043F\u043E\u0440\u0442", uk: "\u0435\u043A\u0441\u043F\u043E\u0440\u0442" },
